 PoliticalGovernanceAgencyIntentCatalog intents;
 AgencyNpcFixture(){agencies.version=2;agencies_state.version=2;common.state().metadata.player_actor_id="deputy";cc->actor_ids={"leader","candidate","deputy"};intents.intents.insert("intent",{"intent","agency.policy","leader","candidate","deputy","leader.policy","delegate.policy","executor.policy",true,false});cc->texts.insert("calm.name","安民");cc->items.insert("grain",{"grain",1,1,false,false});WalletView w;w.id="treasury";w.owner={Owner::Kind::organization,"city"};w.balance=500;common.state().wallets.insert(w.id,w);InventoryView s;s.id="granary";s.owner=w.owner;s.capacity=1000;common.state().inventories.insert(s.id,s);catalog.grants.find("governance")->continuity_policy_id="continue_under_organization";}
 PoliticalGovernanceAgencyContext read(const PoliticalGovernanceAgencyAuthoredOrigin* origin=nullptr){auto x=AgencyMandateFixture::context();x.intents=&intents;x.authored_command=origin;x.player_before=[](Integer,const StableId&)->Outcome<StableId>{return {true,"deputy",{}};};return x;}
 StableId npc(const StableId& actor,const PoliticalGovernanceAgencyCommand& c,PoliticalGovernanceAgencyAuthoredStep step){PoliticalGovernanceAgencyAuthoredOrigin origin{"intent",actor=="leader"?"leader.policy":"delegate.policy",actor,step};auto x=read(&origin);auto q=take(preview_political_governance_agency(x,actor,c));Outcome<StableId> source;if(const auto* issue=std::get_if<PoliticalIssueAgencyGovernance>(&c))source=apply_political_governance_agency_issue_in_candidate(common,governance_state,agencies_state,x,actor,*issue,q);else source=apply_political_governance_agency_mandate_in_candidate(common,agencies_state,x,actor,c,q);auto id=take(source);check(validate_political_governance_agency_sources(read()).ok,"actual NPC source validates without altering selected player");check(common.state().metadata.player_actor_id=="deputy","NPC writer preserves selected player");return id;}
