int main(){try{AgencyNpcFixture f;check(!preview_political_governance_agency(f.read(),"leader",f.proposal()).ok,"untyped NPC call keeps original player guard");auto offer=f.npc("leader",f.proposal(),PoliticalGovernanceAgencyAuthoredStep::offer);auto answer=f.npc("candidate",PoliticalAnswerGovernanceAgency{offer,true},PoliticalGovernanceAgencyAuthoredStep::answer);auto issue=f.npc("candidate",PoliticalIssueAgencyGovernance{offer,answer,"deputy"},PoliticalGovernanceAgencyAuthoredStep::issue);check(f.governance_state.authorities.size()==1&&f.agencies_state.authored_origins.size()==3,"actual original Authority and three exact origins are the only business outputs");check(validate_political_governance_agency_player_results(f.common,f.agencies_state,[](const auto&,const auto&,const auto&){return false;}).ok,"NPC sources do not invent a player result");
 auto old=f.agencies_state.authored_origins;f.agencies_state.authored_origins.erase(issue);check(!validate_political_governance_agency_sources(f.read()).ok,"deleting NPC proof does not become player");f.agencies_state.authored_origins=old;f.agencies_state.issues.find(issue)->player_receipt=PoliticalSuccessionPlayerReceipt{"candidate","result:99",1,1};check(!validate_political_governance_agency_sources(f.read()).ok,"NPC and player result cannot be combined");f.agencies_state.issues.find(issue)->player_receipt.reset();
 auto raw=encode_political_governance_agency_state(f.agencies_state);auto decoded=take(decode_political_governance_agency_state(raw));check(decoded.version==2&&decoded.authored_origins.size()==3,"explicit agency2 JSON keeps exact source table");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);take(visit_political_governance_agency_checkpoint(writer,decoded));take(writer.finish());const auto& immutable=bytes;CodecVisitor reader(immutable);PoliticalGovernanceAgencyState restored;take(visit_political_governance_agency_checkpoint(reader,restored));take(reader.finish());check(compare_boundary(raw,encode_political_governance_agency_state(restored)).exact(),"agency2 typed tail roundtrip");restored.version=1;CodecVisitor::Buffer invalid;CodecVisitor bad(invalid);check(!visit_political_governance_agency_checkpoint(bad,restored).ok,"v1 cannot serialize NPC origin as an empty old tail");
 AgencyNpcFixture late;auto a=late.npc("leader",late.proposal(),PoliticalGovernanceAgencyAuthoredStep::offer);auto b=late.npc("candidate",PoliticalAnswerGovernanceAgency{a,true},PoliticalGovernanceAgencyAuthoredStep::answer);late.common.state().next_instance_id=INT64_MAX-1;auto before=late.common.state();auto state=late.agencies_state;auto governance=late.governance_state;auto token=take(late.common.begin_savepoint());PoliticalGovernanceAgencyAuthoredOrigin origin{"intent","delegate.policy","candidate",PoliticalGovernanceAgencyAuthoredStep::issue};auto x=late.read(&origin);PoliticalIssueAgencyGovernance command{a,b,"deputy"};auto q=take(preview_political_governance_agency(x,"candidate",command));check(!apply_political_governance_agency_issue_in_candidate(late.common,late.governance_state,late.agencies_state,x,"candidate",command,q).ok,"original Authority allocation fails after real signature allocation");take(late.common.rollback_savepoint(token));late.agencies_state=state;late.governance_state=governance;check(late.common.state().facts.order()==before.facts.order()&&late.common.state().next_instance_id==before.next_instance_id&&late.governance_state.authorities.empty()&&late.agencies_state.authored_origins.size()==2,"same candidate restores exact partial original writer failure");std::cout<<checks<<" agency NPC writer assertions; source only\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}

#endif
